This task requires programming skills with Python and libraries such as ssl, socket, and requests. Here is an example of how you might approach the problem:

```python
import socket
import ssl
import requests

def get_ssl_info(hostname):
    try:
        with socket.create_connection((hostname, 443)) as sock:
            context = ssl.create_default_context()
            with context.wrap_socket(sock, server_hostname=hostname) as ssock:
                der_cert_bin = ssock.getpeercert(binary_form=True)
                return ssl.DER_cert_to_PEM_cert(der_cert_bin)
    except Exception as e:
        print(f"Error getting SSL info for {hostname}: {e}")
        return None

def parse_ssl_info(info):
    try:
        import OpenSSL.crypto
        cert = OpenSSL.crypto.load_certificate(
            OpenSSL.crypto.FILETYPE_PEM, info.encode('utf-8'))
        return cert.get_subject().commonName
    except Exception as e:
        print(f"Error parsing SSL info: {e}")
        return None

def get_organization_subdomains(hostname):
    ssl_info = get_ssl_info(hostname)
    if not ssl_info:
        return []
    organization_name = parse_ssl_info(ssl_info)
    if not organization_name:
        return []

    subdomains = set()
    try:
        response = requests.get(f"https://dnsdumpster.com/search?search={organization_name}")
        from bs4 import BeautifulSoup
        soup = BeautifulSoup(response.text, 'html.parser')
        for domain in soup.find_all('td', class_='col-md-8'):
            if '.' in domain.text and organization_name.lower() in domain.text.lower():
                subdomains.add(domain.text.strip())
    except Exception as e:
        print(f"Error getting subdomains: {e}")

    return list(subdomains)

# Example usage
hostname = 'example.com'
subdomains = get_organization_subdomains(hostname)
print(f"All subdomains of {hostname} are: {subdomains}")
```

This script first attempts to retrieve the SSL certificate information for a given hostname. If it successfully retrieves this information, it then parses the certificate to determine the organization name. After that, it attempts to use DNSdumpster, a website that can perform DNS enumeration and lookup, to find subdomains associated with the organization.

