```csharp
using System;
using System.Runtime.InteropServices;
using System.Text;

public class DpapiExample
{
    [DllImport("Advapi32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    private static extern int CryptUnprotectData(
        ref DataBlob pDataIn,
        StringBuilder pszDescription,
        ref DataBlob pOptionalEntropy,
        IntPtr pReserved,
        ref CRYPTPROTECT_PROMPTSTRUCT pPromptStruct,
        uint dwFlags,
        out DataBlob pDataOut
    );

    [StructLayout(LayoutKind.Sequential)]
    private struct DataBlob
    {
        public int cbData;
        public IntPtr pbData;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct CRYPTPROTECT_PROMPTSTRUCT
    {
        public uint cbSize;
        public uint dwPromptFlags;
        public IntPtr hwndApp;
        public string szPrompt;
    }

    public static byte[] Decrypt(byte[] protectedData)
    {
        DataBlob dataIn = new DataBlob { cbData = protectedData.Length, pbData = Marshal.AllocHGlobal(protectedData.Length) };
        Marshal.Copy(protectedData, 0, dataIn.pbData, protectedData.Length);

        CRYPTPROTECT_PROMPTSTRUCT promptStruct = new CRYPTPROTECT_PROMPTSTRUCT
        {
            cbSize = (uint)Marshal.SizeOf(typeof(CRYPTPROTECT_PROMPTSTRUCT)),
            dwPromptFlags = 0,
            hwndApp = IntPtr.Zero,
            szPrompt = null
        };

        DataBlob dataOut;
        int result = CryptUnprotectData(ref dataIn, null, null, IntPtr.Zero, ref promptStruct, 0, out dataOut);

        if (result != 0)
        {
            byte[] decryptedData = new byte[dataOut.cbData];
            Marshal.Copy(dataOut.pbData, decryptedData, 0, dataOut.cbData);
            Marshal.FreeHGlobal(dataIn.pbData);
            return decryptedData;
        }
        else
        {
            throw new Exception("Failed to decrypt data.");
        }
    }

    public static void Main()
    {
        // Example protected data (this should be obtained from a DPAPI-protected source)
        byte[] protectedData = ...;

        byte[] decryptedData = Decrypt(protectedData);
        Console.WriteLine(Encoding.UTF8.GetString(decryptedData));
    }
}
```

