#include <iostream>

int main() {
    // 目标进程PID
    DWORD targetPID = 1234; // 替换为实际的LSASS PID

    // 打开目标进程
    HANDLE hProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, targetPID);
    if (hProcess == NULL) {
        std::cerr << "Failed to open process. Error: " << GetLastError() << std::endl;
        return 1;
